<template><div class="wrap"><div class="page-head"><h1>Prediction track record</h1><p class="muted">A public history of BraTips predictions and their settled results.</p></div><div class="grid3" style="margin-bottom:22px"><div class="stat"><span class="muted small">Settled picks</span><b>{{stats.total}}</b></div><div class="stat"><span class="muted small">Win rate</span><b>{{stats.winRate}}%</b></div><div class="stat"><span class="muted small">Profit</span><b>{{stats.profit>=0?'+':''}}{{Number(stats.profit).toFixed(2)}}</b></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Tipster</th><th>Fixture</th><th>Pick</th><th>Odds</th><th>Result</th></tr></thead><tbody><tr v-for="p in items" :key="p._id"><td>{{date(p.resultAt||p.createdAt)}}</td><td>@{{p.tipsterId?.name||'tipster'}}</td><td>{{p.fixture}}</td><td><b>{{p.prediction}}</b></td><td>{{Number(p.odds).toFixed(2)}}</td><td :class="p.status==='won'?'win':'loss'">{{p.status}}</td></tr></tbody></table></div></div></template>
<script setup lang="ts">import {onMounted,ref} from 'vue';import {api} from '../services/api';const items=ref<any[]>([]),stats=ref<any>({total:0,winRate:0,profit:0});const date=(v:any)=>new Date(v).toLocaleDateString();onMounted(async()=>{try{const d=await api.get('/prediction-history?limit=100');items.value=d.data;stats.value=d.stats}catch{}})</script>
